insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('6b645163-4df5-49c5-9567-f2ab9458ca4e', '751b0bf3-cade-4c69-8ef7-85d4968455ef', 2, 'Càng...càng... (2 sự việc biến đổi song song theo cùng 1 hướng)', 'Vる ＋ にしたがって', 'Diễn tả 2 sự việc/trạng thái cùng biến đổi song song theo cùng 1 chiều hướng', NULL, 67, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bba95bc7-75e6-4f11-89ac-141761997ec2', NULL, 1, 'standard', 'パーティーに行くにせよ行かないにせよ、早く決めてくれないか？', 'Dù có tham gia bữa tiệc hay không, cậu hãy quyết định sớm giúp tớ nhé?', 'パーティーに行くにせよ行かない＿＿＿、早く決めてくれないか？', 'にせよ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bba95bc7-75e6-4f11-89ac-141761997ec2', NULL, 2, 'daily', '結果がどうなるにせよ、最善を尽くすべきだ。', 'Dù kết quả có ra sao, cũng nên cố gắng hết sức.', '結果がどうなる＿＿＿、最善を尽くすべきだ。', 'にせよ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bba95bc7-75e6-4f11-89ac-141761997ec2', NULL, 3, 'daily', '賛成するにせよ反対するにせよ、理由を説明してほしい。', 'Dù tán thành hay phản đối, tôi cũng muốn nghe lý do.', '賛成するにせよ反対する＿＿＿、理由を説明してほしい。', 'にせよ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1dfce87d-497c-4c03-96be-d8298b3e1e3c', NULL, 1, 'standard', '田舎のバスは距離にかかわらず、金額は一律だ。', 'Xe bus ở vùng quê bất kể khoảng cách ra sao thì số tiền cũng đều đồng giá.', '田舎のバスは距離＿＿＿、金額は一律だ。', 'にかかわらず', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1dfce87d-497c-4c03-96be-d8298b3e1e3c', NULL, 2, 'daily', '天気にかかわらず、試合は行われる。', 'Bất kể thời tiết ra sao, trận đấu vẫn được tổ chức.', '天気＿＿＿、試合は行われる。', 'にかかわらず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1dfce87d-497c-4c03-96be-d8298b3e1e3c', NULL, 3, 'daily', '経験の有無にかかわらず、誰でも応募できます。', 'Bất kể có kinh nghiệm hay không, ai cũng có thể ứng tuyển.', '経験の有無＿＿＿、誰でも応募できます。', 'にかかわらず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('51fdc0b3-8b78-4199-93ed-7d4e054c4033', NULL, 1, 'standard', '徹夜して勉強したにもかかわらず、テストの結果は良くなかった。', 'Mặc dù đã thức trắng đêm học bài nhưng kết quả bài kiểm tra không được tốt.', '徹夜して勉強した＿＿＿、テストの結果は良くなかった。', 'にもかかわらず', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('51fdc0b3-8b78-4199-93ed-7d4e054c4033', NULL, 2, 'daily', '雨が降っているにもかかわらず、彼は出かけて行った。', 'Mặc dù trời đang mưa nhưng anh ấy vẫn ra ngoài.', '雨が降っている＿＿＿、彼は出かけて行った。', 'にもかかわらず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('51fdc0b3-8b78-4199-93ed-7d4e054c4033', NULL, 3, 'daily', '若いにもかかわらず、彼はとても落ち着いている。', 'Mặc dù còn trẻ nhưng anh ấy rất điềm tĩnh.', '若い＿＿＿、彼はとても落ち着いている。', 'にもかかわらず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('90dc6760-54ef-4e54-8638-beaf321f16f8', NULL, 1, 'standard', 'あの音楽を聴くにつけ、新婚の頃を思い出す。', 'Cứ mỗi lần nghe bài nhạc đó, tôi lại nhớ đến lúc kết hôn.', 'あの音楽を聴く＿＿＿、新婚の頃を思い出す。', 'につけ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('90dc6760-54ef-4e54-8638-beaf321f16f8', NULL, 2, 'daily', '彼の話を聞くにつけ、感心させられる。', 'Cứ mỗi lần nghe anh ấy nói chuyện, tôi lại thấy khâm phục.', '彼の話を聞く＿＿＿、感心させられる。', 'につけ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('90dc6760-54ef-4e54-8638-beaf321f16f8', NULL, 3, 'daily', '何かにつけ、彼は文句を言う。', 'Cái gì cũng vậy, anh ấy đều than phiền.', '何か＿＿＿、彼は文句を言う。', 'につけ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('601654b8-4723-478b-b558-f3f1afd6a29e', NULL, 1, 'standard', '彼女は周囲の期待に反して大学を中退し、歌手を目指し始めた。', 'Cô ấy trái với kỳ vọng của những người xung quanh, bắt đầu hướng tới mục tiêu trở thành ca sĩ.', '彼女は周囲の期待＿＿＿大学を中退し、歌手を目指し始めた。', 'に反して', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('601654b8-4723-478b-b558-f3f1afd6a29e', NULL, 2, 'daily', '天気予報に反して、今日は晴れた。', 'Trái với dự báo thời tiết, hôm nay trời lại nắng.', '天気予報＿＿＿、今日は晴れた。', 'に反して', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('601654b8-4723-478b-b558-f3f1afd6a29e', NULL, 3, 'daily', '予想に反して、試合は簡単に終わった。', 'Trái với dự đoán, trận đấu đã kết thúc dễ dàng.', '予想＿＿＿、試合は簡単に終わった。', 'に反して', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('aff71de0-8abf-4a01-afbf-47c90972d0e3', NULL, 1, 'standard', '言語レベルに応じて、クラス分けを行う。', 'Tiến hành chia lớp theo trình độ ngôn ngữ.', '言語レベル＿＿＿、クラス分けを行う。', 'に応じて', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('aff71de0-8abf-4a01-afbf-47c90972d0e3', NULL, 2, 'daily', '収入に応じて、税金の額が変わる。', 'Số tiền thuế thay đổi tùy theo thu nhập.', '収入＿＿＿、税金の額が変わる。', 'に応じて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('aff71de0-8abf-4a01-afbf-47c90972d0e3', NULL, 3, 'daily', '状況に応じて、対応を変える必要がある。', 'Cần thay đổi cách xử lý tùy theo tình huống.', '状況＿＿＿、対応を変える必要がある。', 'に応じて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0bd936cf-dc92-4502-a1e3-961641c3bd8e', NULL, 1, 'standard', '明日は大雨に加えて風も強く、ひどい天気になるらしい。', 'Nghe nói ngày mai không chỉ mưa lớn mà gió cũng mạnh, thời tiết rất xấu.', '明日は大雨＿＿＿風も強く、ひどい天気になるらしい。', 'に加えて', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0bd936cf-dc92-4502-a1e3-961641c3bd8e', NULL, 2, 'daily', '給料に加えて、ボーナスも支給される。', 'Ngoài lương ra, còn được trả thêm cả tiền thưởng.', '給料＿＿＿、ボーナスも支給される。', 'に加えて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0bd936cf-dc92-4502-a1e3-961641c3bd8e', NULL, 3, 'daily', '英語に加えて、中国語も勉強している。', 'Ngoài tiếng Anh ra, tôi còn đang học cả tiếng Trung.', '英語＿＿＿、中国語も勉強している。', 'に加えて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c7779c7f-c450-43a2-bee0-f4d8dc5c90eb', '75a8411b-657e-4cae-a04d-898f89017262', 1, 'standard', 'この駐車場は一時間につき800円となります。', 'Bãi đỗ xe này phí mỗi giờ là 800 yên.', 'この駐車場は一時間＿＿＿800円となります。', 'につき', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c7779c7f-c450-43a2-bee0-f4d8dc5c90eb', '75a8411b-657e-4cae-a04d-898f89017262', 2, 'daily', '一人につき、1000円の参加費がかかります。', 'Cứ mỗi người sẽ mất phí tham gia là 1000 yên.', '一人＿＿＿、1000円の参加費がかかります。', 'につき', 'generated');
