insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c7779c7f-c450-43a2-bee0-f4d8dc5c90eb', '3e2aa50e-6465-4511-b4a4-4f232eed31bd', 1, 'standard', 'その映画は好評につき公開期間が延長された。', 'Vì bộ phim được đánh giá cao nên thời hạn công chiếu được kéo dài hơn.', 'その映画は好評＿＿＿公開期間が延長された。', 'につき', 'pdf');
